tr AS (
    SELECT t.mint, m.flip, t.evt_block_time AS ts, t.evt_block_slot AS slot, t.evt_tx_index AS txi,
           t.evt_outer_instruction_index AS oix, t.evt_inner_instruction_index AS iix,
           CAST(COALESCE(t.virtual_sol_reserves, t.virtualSolReserves) AS DOUBLE) / 1e9 AS x
    FROM pumpdotfun_solana.pump_evt_tradeevent t
    JOIN m ON m.mint = t.mint
    WHERE t.evt_block_date BETWEEN DATE '2025-04-07' AND DATE '2025-04-08'
),
k AS (
    SELECT mint, flip, ts, slot, txi, iix, count(*) AS n, count(DISTINCT oix) AS n_oix, count(DISTINCT x) AS n_x
    FROM tr GROUP BY 1, 2, 3, 4, 5, 6
)
SELECT flip, count(DISTINCT mint) AS n_mints,
       count(DISTINCT IF(n > 1, mint)) AS mints_with_tie,
       count(DISTINCT IF(n > 1 AND n_x > 1, mint)) AS mints_tie_diff_x,
       count(DISTINCT IF(n > 1 AND n_oix > 1, mint)) AS mints_tie_diff_oix,
       count_if(n > 1) AS tie_groups, count_if(iix IS NULL) AS groups_iix_null
FROM k GROUP BY 1 ORDER BY 1
